class Solution:
    def maxProfit(self, prices: List[int]) -> int:
        if not prices:
            return 0
        max_profit = 0
        min_price = prices[0]
        for p in prices[1:]:
            if p <= min_price:
                min_price = p
            else:
                max_profit = max(max_profit, p - min_price)
        return max_profit

impl Solution {
  pub fn max_profit(prices: Vec<i32>) -> i32 {
    if prices.is_empty() {
      return 0;
    }
    let mut min_price = prices[0];
    let mut best = 0;
    for &p in &prices[1..] {
      if p < min_price {
        min_price = p;
      } else if p - min_price > best {
        best = p - min_price;
      }
    }
    best
  }
}

